        level: 3,
        lines: [
          { who: 'hal', text: "Frank, you've sold nothing all morning. You've folded that comic four times.", vi: 'Frank, cả sáng nay ông chẳng bán được gì. Ông gấp cuốn truyện đó bốn lần rồi.' },
          { who: 'frank', text: "Ben rang last night. FreshWay's opening in the town. Next spring. Whatever we do.", vi: 'Tối qua Ben gọi. FreshWay sẽ mở ở thị trấn. Mùa xuân năm sau. Nhà tôi làm gì cũng vậy.' },
          { who: 'frank', text: 'Colin! I gave that boy his first job. I fed him crisps for two years!', vi: 'Colin! Tôi cho thằng nhóc đó việc làm đầu tiên. Tôi nuôi nó bằng bim bim suốt hai năm!' },
          { who: 'hal', text: 'Sit down, before you knock the blue box off the stall.', vi: 'Ngồi xuống đi, kẻo ông hất cái hộp xanh rơi khỏi sạp bây giờ.' },
          { who: 'frank', text: "I'll go to his office. I'll say it to his shiny shoes.", vi: 'Tôi sẽ lên văn phòng nó. Tôi sẽ nói thẳng vào đôi giày bóng lộn của nó.' },
          { who: 'hal', text: "And say what? He's an area manager. You're a man with a stall.", vi: 'Rồi nói gì? Nó là quản lý vùng. Còn ông là ông già có cái sạp.' },
          { who: 'frank', text: 'Thirty years, Hal. I painted the sign over that door myself.', vi: 'Ba mươi năm, Hal ạ. Tấm biển trên cửa đó tôi tự tay sơn.' },
          { who: 'frank', text: "What if they're cheaper? What if everybody goes there? What does Ben do then?", vi: 'Lỡ họ bán rẻ hơn? Lỡ ai cũng sang đó? Lúc ấy Ben làm gì?' },
          { who: 'frank', text: "He's never worked anywhere else. Not one single day.", vi: 'Nó chưa từng làm ở đâu khác. Chưa một ngày nào.' },
          { who: 'hal', text: 'When the station supermarket opened a fish counter, I lost a third of my customers.', vi: 'Hồi siêu thị ở nhà ga mở quầy cá, tôi mất một phần ba khách.' },
          { who: 'frank', text: 'I remember. And then what happened?', vi: 'Tôi nhớ. Rồi sau đó thì sao?' },
          { who: 'hal', text: "I'm still here. Smaller. Still moaning. They can't sell what I know.", vi: 'Tôi vẫn ở đây. Nhỏ hơn. Vẫn cằn nhằn. Họ không bán được những gì tôi biết.' },
          { who: 'frank', text: "And what do you know that they don't?", vi: 'Thế anh biết gì mà họ không biết?' },
          { who: 'hal', text: "Who wants their mackerel boned. Who can't pay till Friday.", vi: 'Ai muốn lọc xương cá thu. Ai phải tới thứ Sáu mới trả tiền được.' },
          { who: 'frank', text: 'Ben knows all that. Every name in that town.', vi: 'Ben biết hết mấy chuyện đó. Mọi cái tên trong thị trấn ấy.' },
          { who: 'frank', text: "I don't know what to tell him, Hal. That's the truth.", vi: 'Tôi không biết phải nói gì với nó, Hal ạ. Thật đấy.' },
          { who: 'hal', text: "Then don't tell him anything yet. Ask him what he wants.", vi: 'Thì khoan nói gì đã. Hỏi xem nó muốn gì.' },
          { who: 'frank', text: "Thirty years, and I've never once asked him that.", vi: 'Ba mươi năm, mà tôi chưa hỏi nó câu đó lần nào.' },
        ],
        questions: [
          { q: 'Vì sao cả sáng ông Frank chẳng bán được gì?', options: ['Colin đến tận sạp gây sự', 'Ben đòi bán tiệm cho FreshWay', 'Ông vừa biết FreshWay sẽ mở ở thị trấn'], answer: 2 },
          { q: 'Hal mất bao nhiêu khách khi siêu thị mở quầy cá?', options: ['Một phần ba', 'Một nửa số khách', 'Gần hết khách'], answer: 0 },
          { q: 'Theo Hal, ông Frank nên làm gì?', options: ['Lên văn phòng nói chuyện với Colin', 'Hỏi xem Ben thật sự muốn gì', 'Khuyên Ben bán tiệm cho sớm'], answer: 1 },
        ],
